UPDATE bonus_rules
SET name = CAST(#{name} AS jsonb), bonus_stamps = #{bonusStamps}, days_mask = #{daysMask},
    start_time = #{startTime}, end_time = #{endTime}, starts_on = #{startsOn}, ends_on = #{endsOn},
    branch_id = #{branchId}, active = #{active}, notify_on_start = #{notifyOnStart},
    updated_at = #{now}, updated_by = #{staffId}
WHERE id = #{id}
